// Quasi-static quarter-hemisphere/rigid-plane verification of the native
// solver. Mesh input is generated by scripts/ipc_hertz.py; no Python solver is
// used.
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <numeric>

#include "lib_src/solvers/IpcNewton.h"
#include "lib_utils/cli_utils.h"
#include "lib_utils/surface_trimesh_extract.h"
using namespace tlfea;

int main(int argc, char** argv) {
  try {
    ANCFCPUUtils::Cli cli(argv[0]);
    cli.AddString("mesh", "",
                  "canonical T10 mesh: n m, positions, connectivity");
    cli.AddString("out", "output/logs/ipc_hertz", "output folder");
    cli.AddInt("steps", 4, "prescribed approach increments");
    cli.AddDouble("indent", .001, "indentation after initial gap");
    cli.AddDouble("dhat", 2e-5, "barrier activation distance");
    cli.AddDouble("stiffness", 1000, "physical barrier stiffness");
    std::string error;
    if (!cli.Parse(argc, argv, &error))
      throw std::invalid_argument(error);
    if (cli.HelpRequested()) {
      cli.PrintUsage(std::cout);
      return 0;
    }
    std::ifstream input(cli.GetString("mesh"));
    int n = 0, m = 0;
    input >> n >> m;
    if (n <= 0 || m <= 0)
      throw std::invalid_argument("Missing Hertz mesh");
    Eigen::MatrixXd X(n, 3);
    Eigen::MatrixXi T(m, 10);
    for (int i = 0; i < n; ++i)
      for (int a = 0; a < 3; ++a)
        input >> X(i, a);
    for (int e = 0; e < m; ++e)
      for (int a = 0; a < 10; ++a)
        input >> T(e, a);
    if (!input)
      throw std::invalid_argument("Truncated Hertz mesh");
    const double gap = X.col(2).minCoeff(), top = X.col(2).maxCoeff();
    const double R = top - gap, E = 1e7, nu = .3,
                 effective_E = E / (1 - nu * nu);
    const int steps          = cli.GetInt("steps");
    const double indent      = cli.GetDouble("indent");
    if (steps < 1 || indent <= 0 || gap <= 0)
      throw std::invalid_argument("Invalid Hertz parameters");
    GPU_FEAT10_Data data(m, n);
    data.Initialize();
    data.Setup(Quadrature::tet5pt_x, Quadrature::tet5pt_y, Quadrature::tet5pt_z,
               Quadrature::tet5pt_weights, X.col(0), X.col(1), X.col(2), T);
    // Positive but negligible inertia regularizes static Newton's matrix;
    // report its residual force so this approximation is auditable.
    data.ApplyMaterial(SolidMaterialProperties::SVK(E, nu, 1e-8, 0, 0));
    data.SetExternalForce(Eigen::VectorXd::Zero(3 * n));
    FEAT10GeneralConstraintLayout layout;
    std::vector<int> top_rows;
    layout.j_offsets.push_back(0);
    layout.term_offsets.push_back(0);
    layout.jt_offsets.push_back(0);
    for (int i = 0; i < n; ++i)
      for (int a = 0; a < 3; ++a) {
        const bool fix = (a < 2 && std::abs(X(i, a)) < 1e-9) ||
                         (a == 2 && std::abs(X(i, 2) - top) < 1e-9);
        if (fix) {
          const int row = layout.scalars.size();
          FEAT10GeneralConstraintScalar scalar;
          scalar.node_id = i;
          scalar.axis    = a;
          scalar.target  = X(i, a);
          layout.scalars.push_back(scalar);
          layout.j_columns.push_back(3 * i + a);
          layout.j_offsets.push_back(row + 1);
          layout.term_offsets.push_back(row + 1);
          layout.term_kinds.push_back(kFEAT10ConstraintTermConstant);
          layout.term_scales.push_back(1);
          layout.term_j_indices.push_back(row);
          layout.term_jt_indices.push_back(row);
          layout.jt_columns.push_back(row);
          if (a == 2)
            top_rows.push_back(row);
        }
        layout.jt_offsets.push_back(layout.jt_columns.size());
      }
    data.SetGeneralConstraints(layout);
    auto boundary =
        ANCFCPUUtils::ExtractSurfaceTriMesh(X, T, {0, 0, n, m, "hemisphere"});
    // Exclude the symmetry and loading faces from the contact discretization.
    std::vector<Eigen::Vector3i> curved;
    for (auto f : boundary.triangles) {
      bool flat[3] = {true, true, true};
      for (int v : {f[0], f[1], f[2]})
        for (int a = 0; a < 3; ++a)
          flat[a] = flat[a] && std::abs(boundary.vertices[v][a] -
                                        (a == 2 ? top : 0)) < 1e-9;
      if (!flat[0] && !flat[1] && !flat[2])
        curved.push_back(f);
    }
    // Compact unused surface vertices: Toolkit treats isolated vertices as
    // particles.
    ANCFCPUUtils::SurfaceTriMesh skin;
    std::vector<int> remap(boundary.vertices.size(), -1);
    for (auto f : curved) {
      for (int a = 0; a < 3; ++a) {
        int old = f[a];
        if (remap[old] < 0) {
          remap[old] = skin.vertices.size();
          skin.vertices.push_back(boundary.vertices[old]);
          skin.global_node_ids.push_back(boundary.global_node_ids[old]);
        }
        f[a] = remap[old];
      }
      skin.triangles.push_back(f);
    }
    auto surface = contact::Surface::FromMeshes(X, {skin});
    const int nv = surface.rest.rows(), nf = surface.faces.rows();
    surface.rest.conservativeResize(nv + 4, 3);
    surface.rest.bottomRows(4) << -R, -R, 0, 2 * R, -R, 0, 2 * R, 2 * R, 0, -R,
        2 * R, 0;
    surface.faces.conservativeResize(nf + 2, 3);
    surface.faces.bottomRows(2) << nv, nv + 1, nv + 2, nv, nv + 2, nv + 3;
    surface.W.conservativeResize(nv + 4, n);
    for (int i = 0; i < 4; ++i) {
      surface.body.push_back(1);
      surface.kinematic.push_back(true);
    }
    contact::Config config;
    config.dhat      = cli.GetDouble("dhat");
    config.stiffness = cli.GetDouble("stiffness");
    IpcT10Model model(data);
    IpcNewtonParams params;
    params.time_step            = 1;
    params.min_time_step        = 1e-4;
    params.gradient_atol        = 1e-5;
    params.gradient_rtol        = 1e-8;
    params.constraint_tolerance = 1e-9;
    params.max_newton           = 150;
    IpcNewtonSolver solver(
        data, std::make_unique<contact::IpcContact>(surface, config), params);
    const auto targets = data.GeneralConstraintTargets();
    solver.SetStepInputs([&](double t) {
      IpcStepInputs in;
      in.external_force             = Eigen::VectorXd::Zero(3 * n);
      in.general_constraint_targets = targets;
      for (int row : top_rows)
        in.general_constraint_targets[row] -= (gap + indent) * t / steps;
      return in;
    });
    const auto out = cli.GetString("out");
    std::filesystem::create_directories(out);
    std::ofstream csv(out + "/hertz.csv");
    csv << "approach,force,force_hertz,a_effective,a_hertz,min_J,gap,"
           "constraint,residual,inertial_force,seconds,retries\n"
        << std::setprecision(17);
    for (int k = 0; k < steps; ++k) {
      const auto velocity_before = solver.Velocity();
      const auto r               = solver.Advance(1);
      if (!r.accepted)
        throw std::runtime_error(r.reason);
      const auto x = model.Positions();
      double force = 0, moment = 0;
      for (int i = 0; i < n; ++i) {
        const double f = r.contact_force[3 * i + 2];
        force += f;
        moment += f * x.row(i).head(2).squaredNorm();
      }
      const double a_eff =
          force > 0 ? std::sqrt(std::max(0., 2.5 * moment / force)) : 0;
      force *= 4;
      const double approach = (gap + indent) * solver.time() / steps - gap;
      const double fH       = 4. / 3 * effective_E * std::sqrt(R) *
                        std::pow(std::max(0., approach), 1.5);
      const double aH = std::cbrt(3 * force * R / (4 * effective_E));
      const double inertia =
          (model.mass() * (solver.Velocity() - velocity_before)).norm();
      csv << approach << ',' << force << ',' << fH << ',' << a_eff << ',' << aH
          << ',' << r.min_jacobian << ',' << r.active_min_distance << ','
          << r.constraint_error << ',' << r.residual << ',' << inertia << ','
          << r.elapsed_seconds << ',' << r.retries << '\n';
      csv.flush();
      std::cout << "step=" << k << " force=" << force << " Hertz=" << fH
                << " radius=" << a_eff << " Hertz_radius=" << aH
                << " newton=" << r.newton_iterations << std::endl;
    }
    data.WriteOutputVTU(out + "/final.vtu");
    data.Destroy();
    return 0;
  } catch (const std::exception& e) {
    std::cerr << e.what() << '\n';
    return 1;
  }
}
